// Nœud Code — "Format Error Response"
const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent QA", _version: '5.16',
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;
return [{
  json: {
    model: "claude-sonnet-5",
    messages: [
      { role: "system", content: input.systemPrompt },
      { role: "user",   content: input.userPrompt }
    ],
    temperature: 0,
    max_tokens: 8000
  }
}];

const raw = $input.first().json;
const input = raw.body || raw;
// R5 : une QA qui n'a pas pu analyser (LLM indisponible ou réponse illisible) n'est jamais un succès
if (input._llm_fallback === true || input._parse_error === true || input._parse_error === 'true') {
  return [{ json: { agent: 'Agent QA', _version: '5.16', task_id: input.task_id, status: 'WARN', analysis_failed: true,
    global_score: null, approved_for_pipeline: true, language: input.language, critical_issues: [], warnings: [],
    recommendations: ['Relancer la génération : la revue qualité n’a pas pu être exécutée.'],
    summary: input._llm_fallback ? 'Revue qualité non exécutée : LLM indisponible.' : 'Revue qualité non exécutée : réponse du LLM illisible.',
    dimensions: { security: { score: null }, quality: { score: null } }, timestamp: new Date().toISOString() } }];
}

// V5.14 : seules les anomalies PROUVÉES comptent. Chaque issue doit citer un extrait
// présent mot pour mot dans le code analysé ; sinon elle est écartée (hallucination).
let _ctx = {}, _code = '';
try { const _bp = $('Build Prompt').first().json; _ctx = _bp.qa_context || {}; _code = _bp.code || ''; } catch (e) {}
const _norm = s => String(s || '').replace(/\s+/g, ' ').trim();
const _codeN = _norm(_code);
let _unverified = 0;
const issues = (input.issues || []).filter(i => {
  if (!_codeN) return true;                          // pas de code (mode rapport) : rien à vérifier
  const ev = _norm(i.evidence).replace(/^[`'"]+|[`'"]+$/g, '');
  if (ev.length >= 8 && _codeN.indexOf(ev) >= 0) return true;
  _unverified++; return false;
});
// Couverture mesurée sur les tests générés, jamais estimée par le LLM
const coverage = typeof _ctx.measured_coverage === 'number' ? _ctx.measured_coverage
  : (typeof input.coverage === 'number' ? Math.min(100, Math.max(0, input.coverage)) : 0);
const securityScore = typeof input.security_score === 'number' ? input.security_score : null;
const qualityScore  = typeof input.quality_score  === 'number' ? input.quality_score  : null;
const verdict = (input.verdict || '').toUpperCase();


// ── Filtrage faux positifs — règles déterministes ─────────────────────────
// Le LLM génère des HIGH sur des choix d'architecture MVP → reclasser en WARN

const FALSE_POSITIVE_PATTERNS = [
  // Stockage en mémoire = choix MVP délibéré
  'base de données', 'database', 'stockage en mémoire', 'perte de données',
  'redémarrage du serveur', 'persistance', 'persist',
  // Dotenv déjà utilisé
  'dotenv', 'process.env', 'variables d\'environnement', 'gestion de secrets',
  // Auth / passwords non demandés dans un MVP sans auth
  'authentification', 'autorisation', 'jwt', 'session',
  'mot de passe', 'mots de passe', 'password', 'passwords',
  'bcrypt', 'hash', 'hachage', 'stockage sécurisé',
  'système de stockage', 'système de gestion de secrets',
  'clés api', 'clé api', 'api key',
  // Tests unitaires non demandés
  'tests unitaires', 'tests d\'intégration', 'couverture de test',
  // Style cosmétique
  'noms de variables', 'convention de nommage', 'lisibilité', 'maintenabilité',
  // Validation générique (le Backend déterministe génère déjà les validations)
  'mécanismes de validation', 'validation de données', 'valider les données',
  // Rate limiting / CORS / Helmet → deja en place dans le socle
  'rate limit', 'rate-limit', 'helmet', 'cors', 'limitation de débit',
  // Socle Sprint 2/3 : auth, isolation, migrations, modules, introspection
  'user_id', 'isolation', 'cookie', 'httponly', 'samesite', 'middleware',
  'migration', 'schema_migrations', 'module', 'introspection', 'crypto.randombytes',
  'websocket', 'temps reel', 'roles', 'reinitialisation', 'mot de passe oublie',
  // Logs sensibles → hors périmètre MVP
  'journalisation', 'logs sensibles', 'logging',
  // Gestion erreurs générique → BONNE PRATIQUE OWASP
  'gérées de manière générique', "messages d'erreur personnalisés",
  "informations spécifiques sur l'erreur", 'sans exposer', 'exposer les détails',
  // SQL paramétré → déjà protégé avec db.prepare()
  'sans échappement', 'paramètres pour éviter', 'requêtes préparées', 'injection sql',
  // Date validation → hors périmètre MVP
  'validation pour les champs de date', 'format attendu', 'format de date',
  // Nommage / convention
  'noms de variables', 'noms de fonctions', 'renommer', 'descriptif',
  'lisibilité', 'maintenabilité', 'convention de nommage'
];

for (let i = issues.length - 1; i >= 0; i--) {
  const issue = issues[i];
  if (issue.severity !== 'high') continue;

  const haystack = [
    issue.description || '',
    issue.fix || '',
    issue.impact || ''
  ].join(' ').toLowerCase();

  const isFalsePositive = FALSE_POSITIVE_PATTERNS.some(p => haystack.includes(p));

  if (isFalsePositive) {
    issue.severity = 'medium';
    issue._reclassified = true;
    console.log('⚠️ Faux positif reclassé en WARN: ' + (issue.description || '').substring(0, 60));
  }
}

// Après reclassification, recalculer critical vs warnings
const realCritical = issues.filter(i => i.severity === 'high' && !i._reclassified);
const allWarnings  = issues.filter(i => i.severity !== 'high' || i._reclassified);

function isTrivial(desc) {
  const d = desc.toLowerCase();
  return d.includes('commentaire') || d.includes('indentation') ||
         d.includes('typo') || d.includes('convention de nommage');
}

let critical = [];
let warnings = [];

for (const issue of (realCritical || issues)) {
  const desc = (issue.description || '').trim();
  const sev  = (issue.severity || 'low').toLowerCase();
  if (!desc || isTrivial(desc)) continue;
  if (sev === 'high') critical.push({
    severity: sev, category: issue.category || 'quality',
    file: issue.file || '?', description: desc,
    impact: issue.impact || '', fix: issue.fix || ''
  });
}
for (const issue of (allWarnings || [])) {
  const desc = (issue.description || '').trim();
  const sev  = (issue.severity || 'low').toLowerCase();
  if (!desc || isTrivial(desc)) continue;
  warnings.push({
    severity: sev, category: issue.category || 'quality',
    file: issue.file || '?', description: desc,
    impact: issue.impact || '', fix: issue.fix || ''
  });
}

// ── QA est un gate QUALITE, ADVISORY — pas un gate securite ────────────────
// QA est ADVISORY : la securite est tranchee par les gates DETERMINISTES et
// autoritaires (SAST / SCA / Secrets / DAST) qui STOP le pipeline sur un vrai
// probleme. Un « high » du LLM — meme categorise 'security' — est non
// deterministe (variance de jugement) sur du code deja verifie par les
// scanners ; on le remonte en WARN visible, JAMAIS en blocage. Cela supprime
// les REWORK intempestifs et respecte l'architecture (LLM = comprehension,
// deterministe = securite).
warnings = warnings.concat(critical); // tous les highs LLM deviennent des WARN
critical  = [];
const _blocking = []; // QA ne bloque jamais le pipeline

let status;
if (_blocking.length > 0) {
  status = 'FAIL'; // uniquement une vraie vulnerabilite securite non filtree
} else if (verdict === 'FAIL' || verdict === 'WARN' || warnings.filter(w => w.severity === 'medium').length >= 3 || coverage < 50) {
  status = 'WARN'; // signalements qualite — n'arrete PAS le pipeline
} else {
  status = 'PASS';
}
// Réponse coupée ou extrait réduit (modèle de secours) : jamais un PASS plein
const _incomplete = input._truncated === true || input._partial_input === true;
if (_incomplete && status === 'PASS') status = 'WARN';

// Scores V5.14 : calculés à partir des anomalies PROUVÉES (le LLM ne note plus lui-même)
const _pen = (list, cat) => list.filter(i => !cat || i.category === cat).reduce((s, i) => s + (i.severity === 'high' ? 15 : i.severity === 'medium' ? 5 : 1), 0);
const secScore  = Math.max(0, 100 - _pen(warnings, 'security'));
const qualScore = Math.max(0, 100 - _pen(warnings.filter(i => i.category !== 'security')));
const globalScore = Math.round(secScore * 0.3 + qualScore * 0.5 + coverage * 0.2);

return [{
  json: {
    agent: 'Agent QA', _version: '5.16',
    task_id: input.task_id,
    status,
    global_score: globalScore,
    approved_for_pipeline: status !== 'FAIL', // WARN laisse passer
    language: input.language,
    critical_issues: critical,
    warnings,
    recommendations: input.recommendations || [],
    summary: input.summary || '',
    verdict_llm: verdict,
    coverage_measured: coverage,
    unverified_issues_dropped: _unverified,
    analysis_scope: _incomplete ? ('partiel : ' + (input._partial_input ? 'extrait réduit (modèle de secours)' : 'réponse du modèle coupée')) : (_ctx.omitted && _ctx.omitted.length ? ('partiel : ' + _ctx.omitted.join(', ')) : 'complet'),
    dimensions: {
      security: { score: secScore },
      quality:  { score: qualScore }
    },
    timestamp: new Date().toISOString()
  }
}];

// ── Télémétrie LLM -> panel (crédits Tchavi, fournisseur, tokens) — ne bloque jamais ──
try {
  const _tr = ($input.first() || {}).json || {};
  if (_tr.choices) {
    const _tu = _tr.usage || {};
    const _tn = function (v) { return typeof v === 'number' ? v : (typeof v === 'string' && v.trim() !== '' && !isNaN(+v) ? +v : undefined); };
    const _tc = [_tr.credits_remaining, _tu.credits_remaining, _tr.tchavi && _tr.tchavi.credits_remaining,
                 _tr.billing && _tr.billing.credits_remaining, _tr.credits && _tr.credits.remaining].map(_tn).find(function (v) { return v !== undefined; });
    await this.helpers.httpRequest({
      method: 'POST', url: ($env.PANEL_TELEMETRY_URL || 'http://forge-panel:3001/telemetry'),
      body: { agent: 'qa', model: _tr.model || null,
        provider: _tr.x_groq ? 'groq' : ((_tc !== undefined || /claude|gpt|^llama-3\.3-70b$/i.test(_tr.model || '')) ? 'tchavi' : 'fallback'),
        prompt_tokens: _tu.prompt_tokens || 0, completion_tokens: _tu.completion_tokens || 0, total_tokens: _tu.total_tokens || 0,
        credits_remaining: (_tc === undefined ? null : _tc), ts: Date.now() },
      json: true, timeout: 1500 });
  }
} catch (e) {}

const llmResponse = $input.first().json;

// Référence explicite au nœud Validate Input
const upstream = $('Validate Input').first().json;

const raw = llmResponse.choices?.[0]?.message?.content;

if (!raw) {
  return [{
    json: {
      task_id: upstream.task_id,
      language: upstream.language,
      issues: [],
      coverage: 0,
      recommendations: [],
      summary: "Erreur : réponse LLM vide",
      received_at: upstream.received_at,
      _parse_error: true
    }
  }];
}

// Lecture tolérante : le modèle peut entourer le JSON de texte, ou être coupé par
// max_tokens (finish_reason = length). On récupère alors chaque anomalie COMPLÈTE déjà
// écrite au lieu de déclarer toute l'analyse illisible.
function _tryParse(s) { try { return JSON.parse(s); } catch (e) { return null; } }
function _objectsIn(s) {
  // s commence au « [ » du tableau issues : on extrait chaque objet de premier niveau terminé
  const out = []; let depth = 0, start = -1, inStr = false, esc = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '[' || ch === '{') { if (ch === '{' && depth === 1) start = i; depth++; }
    else if (ch === ']' || ch === '}') { depth--; if (ch === '}' && depth === 1 && start >= 0) { const o = _tryParse(s.slice(start, i + 1)); if (o) out.push(o); start = -1; } if (depth <= 0) break; }
  }
  return out;
}
let parsed = {};
const _finish = llmResponse.choices?.[0]?.finish_reason || '';
const cleaned = String(raw).replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const _a = cleaned.indexOf('{'), _b = cleaned.lastIndexOf('}');
parsed = _tryParse(cleaned) || (_a >= 0 && _b > _a ? _tryParse(cleaned.slice(_a, _b + 1)) : null);
if (!parsed) {
  const _iStart = cleaned.indexOf('"issues"');
  const salvaged = _iStart >= 0 ? _objectsIn(cleaned.slice(cleaned.indexOf('[', _iStart))).filter(o => o && typeof o.severity === 'string' && typeof o.description === 'string') : [];
  if (_iStart >= 0) {
    parsed = { issues: salvaged, recommendations: [], summary: 'Réponse du modèle coupée (' + (_finish || 'longueur') + ') : ' + salvaged.length + ' anomalie(s) complète(s) récupérée(s).', _truncated: true };
  } else {
    parsed = { issues: [], coverage: 0, recommendations: [], summary: 'Réponse du LLM illisible (aucun JSON)', _parse_error: true };
  }
}
// Analyse réalisée par le modèle de secours sur un extrait réduit ?
let _partial = false;
try { const _fp = $('Fallback Payload').first().json; _partial = JSON.stringify(_fp.messages || []).indexOf('[extrait réduit') >= 0; } catch (e) {}

const issues = Array.isArray(parsed.issues) ? parsed.issues.filter(i =>
  i && typeof i.severity === 'string' && typeof i.description === 'string'
) : [];

return [{
  json: {
    task_id: upstream.task_id,
    language: upstream.language,
    issues,
    coverage: typeof parsed.coverage === 'number'
      ? Math.min(100, Math.max(0, parsed.coverage))
      : 0,
    recommendations: Array.isArray(parsed.recommendations)
      ? parsed.recommendations
      : [],
    summary: parsed.summary || "",
    security_score: typeof parsed.security_score === 'number' ? parsed.security_score : null,
    quality_score:  typeof parsed.quality_score  === 'number' ? parsed.quality_score  : null,
    verdict: parsed.verdict || '',
    _parse_error: parsed._parse_error === true,
    _truncated: parsed._truncated === true,
    _partial_input: _partial,
    received_at: upstream.received_at
  }
}];

const input = $input.first().json;

// V5.14 : le code est assemblé PAR FICHIER, par ordre d'importance, au lieu d'être coupé
// à 40 000 caractères (DiaspoKoli : la QA ne lisait que la moitié de server.js).
const files = Array.isArray(input.files) ? input.files : [];
const strip = s => String(s || '').replace(/^(\/\/|--|<!--|\/\*) FILE:.*\n/, '');
const PRIORITY = [/^server\.js$/, /^schema\.sql$/, /^db\.js$/, /^tests\//, /^package\.json$/, /^frontend\/app\.js$/, /^frontend\/index\.html$/, /^frontend\/login\.html$/];
const CAP = { 'server.js': 170000, 'frontend/app.js': 20000, 'frontend/index.html': 8000 };
const BUDGET = 220000;   // ≈ 55 000 jetons : server.js complet + schéma + tests
const ordered = files.filter(f => f && f.path && !/\.(md|css|svg|png|ico)$|^bom\.json$|^\.|Dockerfile|docker-compose|nginx/.test(f.path))
  .sort((x, y) => { const r = p => { const i = PRIORITY.findIndex(re => re.test(p)); return i < 0 ? 99 : i; }; return r(x.path) - r(y.path); });
let used = 0; const parts = []; const omitted = [];
ordered.forEach(f => {
  let c = strip(f.content); const cap = CAP[f.path] || 15000;
  if (used >= BUDGET) { omitted.push(f.path); return; }
  if (c.length > cap) { c = c.slice(0, cap) + '\n/* … ' + f.path + ' : suite non transmise (' + (c.length - cap) + ' caractères) */'; omitted.push(f.path + ' (partiel)'); }
  used += c.length; parts.push('// FILE: ' + f.path + '\n' + c);
});
let code = parts.length ? parts.join('\n\n') : String(input.code || '').slice(0, BUDGET);

// Couverture MESURÉE (jamais demandée au LLM) : routes métier exercées par les tests générés
const srv = strip((files.find(f => f.path === 'server.js') || {}).content);
const tst = files.filter(f => /^tests\//.test(f.path)).map(f => strip(f.content)).join('\n');
const routes = Array.from(new Set((srv.match(/app\.(get|post|put|patch|delete)\(\s*'(\/[^']*)'/g) || []).map(s => s.replace(/app\.\w+\(\s*'/, '').replace(/'$/, ''))));
const resRoots = Array.from(new Set(routes.map(r => r.split('/')[1]).filter(Boolean)));
const tested = resRoots.filter(r => new RegExp("['\"`]/" + r.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + "(['\"`/]|$)").test(tst));
const testCount = (tst.match(/\btest\(/g) || []).length;
const measuredCoverage = resRoots.length ? Math.round(100 * tested.length / resRoots.length) : 0;
const qaContext = { routes: routes.length, resources_with_routes: resRoots, resources_tested: tested, tests: testCount, measured_coverage: measuredCoverage, omitted };

const systemPrompt = `Tu es un expert QA senior et DevSecOps spécialisé Node.js/Express.
Tu analyses le code en profondeur et fournis des détails ACTIONNABLES pour chaque problème.

━━━ FORMAT DE SORTIE OBLIGATOIRE ━━━
{
  "issues": [
    {
      "severity": "high|medium|low",
      "category": "security|quality|functionality|performance",
      "file": "server.js",
      "description": "description précise du problème",
      "impact": "conséquence concrète si non corrigé",
      "fix": "exemple de correction en 1-2 lignes de code",
      "evidence": "extrait exact du code qui prouve le problème"
    }
  ],
  "coverage": 85,
  "security_score": 90,
  "quality_score": 80,
  "recommendations": ["action concrète et prioritaire"],
  "summary": "résumé en une phrase",
  "verdict": "PASS|FAIL|WARN"
}

━━━ SÉVÉRITÉS ━━━

HIGH (bloquant — crash ou faille critique) :
  - require() vers fichier inexistant → crash au démarrage
  - Variable undefined sans vérification → crash runtime
  - Secret hardcodé (API key, password) → faille sécurité critique
  - eval() ou innerHTML avec données utilisateur → injection/XSS
  - Pas de validation sur données entrantes → injection possible
  - res.json([]) statique au lieu du store → perte de données
  - app.listen() sans PORT → non configurable

MEDIUM (comportement incorrect ou risque modéré) :
  - Code HTTP incorrect (200 pour création, utiliser 201)
  - Absence de try/catch sur endpoint
  - express.static absent avec frontend/
  - Pas de Content-Type validé sur POST
  - console.log avec données utilisateur (fuite info)

LOW (amélioration non urgente) :
  - Console.log de debug oubliés
  - Nommage peu descriptif
  - Code dupliqué mineur

━━━ CHECKS SÉCURITÉ OBLIGATOIRES (DevSecOps) ━━━
1. Secrets hardcodés : chercher password=, apikey=, SECRET=, TOKEN= avec valeurs
2. Injection XSS : innerHTML, document.write avec données non échappées
3. Injection SQL/NoSQL : concaténation dans requêtes
4. eval() ou Function() avec données utilisateur
5. Validation inputs : tous les champs POST sont-ils validés ?
6. Gestion erreurs : les messages d'erreur exposent-ils des infos sensibles ?

━━━ NE PAS SIGNALER ━━━
- Absence de commentaires ou documentation
- Style (tabs/spaces, nommage subjectif)
- Stockage en mémoire → c'est un choix valide
- Absence de tests unitaires
- Optimisations prématurées

━━━ VERDICT ━━━
- PASS  : 0 high, coverage >= 60
- WARN  : 0 high, coverage 40-59 OU 1-2 medium
- FAIL  : 1+ high OU coverage < 40

Sois précis et actionnable. Au plus 15 anomalies, les plus graves d'abord ; descriptions et corrections courtes (2 lignes max). Réponds UNIQUEMENT par le JSON, sans texte autour. Chaque issue doit avoir un fix concret.`;

const userPrompt = code
  ? `Contexte mesuré : ${JSON.stringify(qaContext)}\nLe code est généré : les règles métier appliquées sont listées en tête de server.js. Ne signale que des défauts PROUVÉS par le code fourni ; pour chacun, recopie dans "evidence" un extrait EXACT (une ligne, 120 caractères max) qui le démontre. N'invente rien sur les fichiers omis.\n\nAnalyse ce code ${input.language} :\n\n\`\`\`${input.language}\n${code}\n\`\`\``
  : `Évalue ce rapport pour le projet ${input.language} :\n${JSON.stringify({
      issues: input.issues,
      coverage: input.coverage,
      recommendations: input.recommendations
    }, null, 2)}`;

return [{
  json: {
    ...input,
    code,
    qa_context: qaContext,
    systemPrompt,
    userPrompt
  }
}];

const raw = $input.first().json;

let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object' && Object.keys(rawBody).length > 0) {
    data = rawBody;
  }
}

const hasDirectData = (
  Array.isArray(data.issues) &&
  data.issues.length > 0 &&
  data.coverage !== undefined &&
  data.code === undefined
);

if (!data.task_id) {
  return [{
    json: {
      valid: false,
      error_code: "VALIDATION_ERROR",
      error_message: "task_id manquant dans le payload entrant",
      received_payload: data,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    valid: true,
    task_id: data.task_id,
    language: (data.language || "javascript").toLowerCase().trim(),
    issues: data.issues || [],
    coverage: data.coverage ?? 0,
    recommendations: data.recommendations || [],
    code: data.code || null,
    files: Array.isArray(data.files) ? data.files : [],   // V5.14 (R3) : nécessaire à l'analyse par fichier
    skipLLM: hasDirectData,
    received_at: new Date().toISOString()
  }
}];

// Fallback QA : Mistral indisponible — retourner WARN pour laisser le pipeline continuer
const upstream = $('Validate Input').first().json;
return [{
  json: {
    task_id:   upstream.task_id || 'unknown',
    language:  upstream.language || 'javascript',
    issues: [],
    coverage: null,
    verdict: 'WARN',
    status: 'WARN',
    security_score: null,
    quality_score: null,
    recommendations: ['QA non exécutée — quota LLM atteint. Relancer pour une analyse complète.'],
    summary: 'QA NON exécutée (échec LLM) — verdict non concluant, à relancer.',
    _llm_fallback: true
  }
}];

// Charge utile du failover (LLM gratuit, ex. Groq) — construite ici car $('…').first()
// ne se résout pas dans le body d'un httpRequest (règle R2). Le nœud HTTP envoie ={{ $json }}.
const src = $('Build Payload QA').first().json;
const _maxIn = Number($env.FALLBACK_LLM_MAX_INPUT_CHARS) || 24000;
const _msgs = (src.messages || []).map(m => Object.assign({}, m));
const _sys = _msgs.filter(m => m.role === 'system').reduce((s, m) => s + String(m.content || '').length, 0);
_msgs.forEach(m => {
  if (m.role !== 'user') return;
  const room = Math.max(4000, _maxIn - _sys);
  const s = String(m.content || '');
